// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { EmptyStateProps } from "./empty-state.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "EmptyState";

// Generate child element class names for the component, should match available style slots
export const EmptyStateClasses = {
  root: "exp-textura_empty-state",
  sm: "exp-textura_empty-state_sm",
  image: "exp-textura_empty-state_image",
  content: "exp-textura_empty-state_content",
  title: "exp-textura_empty-state_title",
  description: "exp-textura_empty-state_description",
  actions: "exp-textura_empty-state_actions",
  footerText: "exp-textura_empty-state_footer-text",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: EmptyStateProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<EmptyStateProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    gap: theme.toRem(theme.spacing[24]),
    textAlign: "center",
    width: "100%",
    height: "100%",

    [`.${EmptyStateClasses.image}`]: {
      width: 64,
      height: 64,
      backgroundColor: theme.color.steel[300],
      color: theme.color.steel[700],
      fontSize: theme.toRem(24),
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      ...styleSlots?.image,
    },

    [`.${EmptyStateClasses.content}`]: {
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      maxWidth: theme.toRem(460),
      width: "100%",
      ...styleSlots?.content,
    },

    [`.${EmptyStateClasses.title}`]: {
      ...theme.typography.heading.sm,
      color: theme.color.content.default,
      margin: 0,
      ...styleSlots?.title,
    },

    [`.${EmptyStateClasses.description}`]: {
      ...theme.typography.body.mdAccent,
      color: theme.color.content.weak,
      margin: 0,
      // maxWidth removed from here as it should be on the container
      ...styleSlots?.description,
    },

    [`.${EmptyStateClasses.actions}`]: {
      display: "flex",
      gap: theme.toRem(theme.spacing[12]),
      ...styleSlots?.actions,
    },

    [`.${EmptyStateClasses.footerText}`]: {
      ...theme.typography.body.md,
      color: theme.color.content.weak,
      ...styleSlots?.footerText,
    },

    [`&.${EmptyStateClasses.sm}`]: {
      gap: theme.toRem(theme.spacing[8]),

      [`.${EmptyStateClasses.image}`]: {
        width: 40,
        height: 40,
        fontSize: theme.toRem(16),
        ...styleSlots?.imageSm,
      },

      [`.${EmptyStateClasses.content}`]: {
        gap: 0,
        ...styleSlots?.contentSm,
      },

      [`.${EmptyStateClasses.title}`]: {
        ...theme.typography.label.md,
        ...styleSlots?.titleSm,
      },

      [`.${EmptyStateClasses.description}`]: {
        ...theme.typography.body.md,
        ...styleSlots?.descriptionSm,
      },

      [`.${EmptyStateClasses.actions}`]: {
        marginTop: theme.toRem(theme.spacing[8]),
        ...styleSlots?.actionsSm,
      },

      ...styleSlots?.sm,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledEmptyState = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<EmptyStateProps>((props) => generateStyles(props));
